import 'package:cloud_firestore/cloud_firestore.dart';
class FirestoreDataSource { FirestoreDataSource(this._db); final FirebaseFirestore _db; CollectionReference<Map<String,Object?>> collection(String path)=>_db.collection(path); Stream<List<QueryDocumentSnapshot<Map<String,Object?>>>> watch(String path,{String? orderBy})=> (orderBy == null ? _db.collection(path) : _db.collection(path).orderBy(orderBy,descending:true)).snapshots().map((s)=>s.docs); Future<void> save(String path,String id,Map<String,Object?> data)=>_db.collection(path).doc(id).set(data,SetOptions(merge:true)); Future<void> delete(String path,String id)=>_db.collection(path).doc(id).delete(); }
